   561        }
   562      } else if (IsInt()) {
   563        s += flatbuffers::NumToString(AsInt64());
   564      } else if (IsUInt()) {
   565        s += flatbuffers::NumToString(AsUInt64());
   566      } else if (IsFloat()) {
   567        s += flatbuffers::NumToString(AsDouble());
   568      } else if (IsNull()) {
   569        s += "null";
   570      } else if (IsBool()) {
   571        s += AsBool() ? "true" : "false";
   572      } else if (IsMap()) {
   573        s += "{ ";
   574        auto m = AsMap();
   575        auto keys = m.Keys();
   576        auto vals = m.Values();
   577        for (size_t i = 0; i < keys.size(); i++) {
   578          keys[i].ToString(true, keys_quoted, s);
   579          s += ": ";
   580          vals[i].ToString(true, keys_quoted, s);
   581          if (i < keys.size() - 1) s += ", ";
   582        }
   583        s += " }";
   584      } else if (IsVector()) {
   585        AppendToString<Vector>(s, AsVector(), keys_quoted);
   586      } else if (IsTypedVector()) {
   587        AppendToString<TypedVector>(s, AsTypedVector(), keys_quoted);
   588      } else if (IsFixedTypedVector()) {
   589        AppendToString<FixedTypedVector>(s, AsFixedTypedVector(), keys_quoted);
   590      } else if (IsBlob()) {
   591        auto blob = AsBlob();
   592        flatbuffers::EscapeString(reinterpret_cast<const char *>(blob.data()),
   593                                  blob.size(), &s, true, false);
   594      } else {
   595        s += "(?)";
   596      }
   597    }
