  1708    bool VerifyVector(const uint8_t *p, Type elem_type, uint8_t size_byte_width,
  1709                      uint8_t elem_byte_width) {
  1710      // Any kind of nesting goes thru this function, so guard against that
  1711      // here.
  1712      if (AlreadyVerified(p))
  1713        return true;
  1714      if (!VerifyBeforePointer(p, size_byte_width))
  1715        return false;
  1716      auto sized = Sized(p, size_byte_width);
  1717      auto num_elems = sized.size();
  1718      auto max_elems = SIZE_MAX / elem_byte_width;
  1719      if (!Check(num_elems < max_elems))
  1720        return false;  // Protect against byte_size overflowing.
  1721      auto byte_size = num_elems * elem_byte_width;
  1722      if (!VerifyFromPointer(p, byte_size))
  1723        return false;
  1724      if (!IsInline(elem_type)) {
  1725        if (elem_type == FBT_NULL) {
  1726          // Verify type bytes after the vector.
  1727          if (!VerifyFromPointer(p + byte_size, num_elems)) return false;
  1728          auto v = Vector(p, size_byte_width);
  1729          for (size_t i = 0; i < num_elems; i++)
  1730            if (!VerifyRef(v[i])) return false;
  1731        } else if (elem_type == FBT_KEY) {
  1732          auto v = TypedVector(p, elem_byte_width, FBT_KEY);
  1733          for (size_t i = 0; i < num_elems; i++)
  1734            if (!VerifyRef(v[i])) return false;
  1735        } else {
  1736          FLATBUFFERS_ASSERT(false);
  1737        }
  1738      }
  1739      MarkVerified(p);
  1740      return true;
  1741    }
  1742
  1743    bool VerifyKeys(const uint8_t *p, uint8_t byte_width) {
  1744      // The vector part of the map has already been verified.
  1745      const size_t num_prefixed_fields = 3;
  1746      if (!VerifyBeforePointer(p, byte_width * num_prefixed_fields))
  1747        return false;
  1748      p -= byte_width * num_prefixed_fields;
  1749      auto off = ReadUInt64(p, byte_width);
  1750      if (!VerifyOffset(off, p))
  1751        return false;
  1752      auto key_byte_with =
  1753        static_cast<uint8_t>(ReadUInt64(p + byte_width, byte_width));
  1754      if (!VerifyByteWidth(key_byte_with))
  1755        return false;
  1756      return VerifyVector(p - off, FBT_KEY, key_byte_with, key_byte_with);
  1757    }
