  1759    bool VerifyKey(const uint8_t* p) {
  1760      if (AlreadyVerified(p)) return true;
  1761      MarkVerified(p);
  1762      while (p < buf_ + size_)
  1763        if (*p++) return true;
  1764      return false;
  1765    }
